"""Give every test the `beam` fixture, so each notebook's copy is exercised."""

import re
from pathlib import Path

path = Path("D:/research/tests/test_beam.py")
text = path.read_text(encoding="utf-8")

SKIP = {
    "test_at_least_one_notebook_carries_the_implementation",  # does not use the fixture
}

pattern = re.compile(r"^def (test_\w+)\(([^)]*)\):", re.MULTILINE)


def rewrite(match):
    name, args = match.group(1), match.group(2).strip()
    if name in SKIP:
        return match.group(0)
    if args.split(",")[0].strip() == "beam":
        return match.group(0)
    new_args = "beam" if not args else f"beam, {args}"
    return f"def {name}({new_args}):"


new_text, count = pattern.subn(rewrite, text)
path.write_text(new_text, encoding="utf-8")

remaining = [
