"""Measure C: (internal NVMe) read speed on a large file, from a deep offset.

The pagefile lives on C:, so this number - not the T7's - is what sets how fast
SSD-as-RAM could possibly be.
"""

import time
from pathlib import Path

CHUNK = 8 * 1024 * 1024

candidates = []
for root in (Path("C:/Windows/Installer"), Path("C:/ProgramData"), Path("C:/Windows/WinSxS"),
             Path("C:/Program Files"), Path("C:/Users/sathi/AppData/Local")):
    if not root.exists():
        continue
    try:
        for path in root.rglob("*"):
            try:
                if path.is_file() and path.stat().st_size > 400_000_000:
                    candidates.append(path)
                    if len(candidates) >= 4:
                        break
            except OSError:
                continue
    except OSError:
        continue
    if len(candidates) >= 4:
        break

if not candidates:
    print("no large file found on C: to benchmark")
    raise SystemExit(0)

for path in candidates[:3]:
    size = path.stat().st_size
    offset = int(size * 0.3)
    limit = min(1_200_000_000, size - offset)
    total = 0
    start = time.perf_counter()
    try:
        with open(path, "rb", buffering=0) as handle:
            handle.seek(offset)
            while total < limit:
                block = handle.read(CHUNK)
                if not block:
                    break
                total += len(block)
    except OSError as exc:
        print(f"  skipped {path.name}: {exc}")
        continue
    seconds = time.perf_counter() - start
    mib = total / 2**20
    print(f"  {mib / seconds:8,.0f} MiB/s   {mib:6,.0f} MiB in {seconds:5.2f}s   {path.name}")

